    for &a in alphabet {
        for &b in alphabet {
            let input = [a, b];
            let expected = reference::decode(&input).unwrap();
            let mut output = [0xa5; 2];
            let n = decode(&input, &mut output, &mut [0; 1]).unwrap();
            assert_eq!(&output[..n], expected);
