    ] {
        check(&vec![0; len]);
        check(&vec![255; len]);
        check(&vec![0x55; len]);
        check(&reference::random(&mut seed, len));
        let mut leading = vec![0; len];
        if len != 0 {
            leading[len - 1] = 255;
        }
        check(&leading);
