fn checked_capacity_boundaries() {
    for n in (0..10000).chain([
        usize::MAX,
        usize::MAX - 1,
        usize::MAX / 138,
        usize::MAX / 2,
        usize::MAX / 138 * 100,
        usize::MAX / 138 * 100 + 99,
