        let expected = usize::try_from(cap).ok();
        assert_eq!(z58::encoded_capacity(n), expected);
        assert_eq!(z58::decoded_capacity(n), Some(n));
        assert_eq!(
            z58::encode_scratch_len(n),
            Some(((wide * 138 + 499) / 500) as usize)
        );
